<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import PageFrame from '@/components/common/PageFrame.vue';
import { cipherRegistry } from '@/services/ciphers/registry';
import { runCipher } from '@/services/ciphers/registry';
import type { CipherOptions } from '@/models/cipher';

const lessonOptions: Record<CipherOptions['kind'], CipherOptions> = { caesar: { kind: 'caesar', shift: 3 }, vigenere: { kind: 'vigenere', key: 'LEMON' }, atbash: { kind: 'atbash' }, affine: { kind: 'affine', a: 5, b: 8 }, 'rail-fence': { kind: 'rail-fence', rails: 3 }, columnar: { kind: 'columnar', key: 'ZEBRAS' }, playfair: { kind: 'playfair', key: 'PLAYFAIR EXAMPLE' }, hill: { kind: 'hill', key: 'GYBNQKURP', size: 3 }, autokey: { kind: 'autokey', key: 'QUEENLY' } };
const examples: Record<CipherOptions['kind'], string> = { caesar: 'HELLO', vigenere: 'ATTACKATDAWN', atbash: 'HELLO', affine: 'AFFINECIPHER', 'rail-fence': 'WEAREDISCOVEREDFLEEATONCE', columnar: 'WE ARE DISCOVERED', playfair: 'HIDETHEGOLDINTHETREESTUMP', hill: 'ACT', autokey: 'ATTACKATDAWN' };
const selectedId = ref<CipherOptions['kind']>('caesar'); const view = ref<'simple' | 'technical'>('simple'); const stepIndex = ref(0); const exercise = ref(''); const answer = ref('');
const cipher = computed(() => cipherRegistry.find((item) => item.id === selectedId.value) ?? cipherRegistry[0]);
const result = computed(() => runCipher(examples[selectedId.value], lessonOptions[selectedId.value], 'encrypt'));
const currentStep = computed(() => result.value.steps[Math.min(stepIndex.value, Math.max(0, result.value.steps.length - 1))]);
watch(selectedId, () => { stepIndex.value = 0; exercise.value = ''; answer.value = ''; });
function check() { try { const expected = runCipher(exercise.value, lessonOptions[selectedId.value], 'encrypt').output; answer.value = expected; } catch (error) { answer.value = error instanceof Error ? error.message : 'Try again.'; } }
</script>

<template>
  <PageFrame title="Learning mode" eyebrow="INTERACTIVE CRYPTOGRAPHY" back back-to="/home" back-label="Home" wide>
    <section class="learning-hero"><div><span class="kicker">Method, movement, meaning</span><h1>Learn by<br />stepping through.</h1></div><p class="lead">Every classical method includes its limitations. Switch between an intuition-first explanation and the actual modular or structural operation.</p></section>
    <section class="lesson-layout">
      <aside class="lesson-index"><button v-for="item in cipherRegistry" :key="item.id" type="button" :class="{ active: item.id === selectedId }" @click="selectedId = item.id"><span>{{ item.family }}</span><strong>{{ item.name }}</strong></button></aside>
      <div class="stack">
        <section class="terminal-panel lesson-heading"><span class="badge badge--warning">Educational / not secure</span><h2>{{ cipher.name }}</h2><p class="lead">{{ cipher.description }}</p><div class="segmented"><button type="button" :class="{ active: view === 'simple' }" @click="view = 'simple'">Simple explanation</button><button type="button" :class="{ active: view === 'technical' }" @click="view = 'technical'">Technical steps</button></div></section>
        <section v-if="view === 'simple'" class="terminal-panel visual-stage">
          <template v-if="selectedId === 'caesar' || selectedId === 'atbash'"><div class="alphabet-strip"><span v-for="letter in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'" :key="letter">{{ letter }}</span></div><div class="alphabet-strip shifted"><span v-for="letter in (selectedId === 'caesar' ? 'DEFGHIJKLMNOPQRSTUVWXYZABC' : 'ZYXWVUTSRQPONMLKJIHGFEDCBA')" :key="letter">{{ letter }}</span></div><p>Match a letter in the top row to its transformed partner below.</p></template>
          <template v-else-if="selectedId === 'vigenere' || selectedId === 'autokey'"><div class="alignment mono"><span>TEXT&nbsp; {{ examples[selectedId] }}</span><span>KEY&nbsp;&nbsp; {{ String(result.metadata?.runningKey ?? '').slice(0, examples[selectedId].length) }}</span><strong>OUT&nbsp;&nbsp; {{ result.output }}</strong></div><p>The key advances only when the input character is a Latin letter.</p></template>
          <template v-else-if="selectedId === 'affine'"><div class="formula">E(x) = (5x + 8) mod 26</div><p>Each letter becomes a number. Multiply, add, then wrap around the alphabet.</p></template>
          <template v-else-if="selectedId === 'rail-fence'"><pre class="diagram">{{ result.metadata?.diagram }}</pre><p>The zigzag changes positions, not the characters themselves.</p></template>
          <template v-else-if="selectedId === 'columnar'"><div class="grid-visual"><span v-for="row in (result.metadata?.grid as string[] ?? [])" :key="row">{{ row }}</span></div><p>Columns are read by alphabetical keyword rank; duplicate letters keep left-to-right order.</p></template>
          <template v-else-if="selectedId === 'playfair'"><div class="key-square"><span v-for="letter in (result.metadata?.square as string[] ?? [])" :key="letter">{{ letter }}</span></div><p>I and J share a cell. Repeated letters in a pair receive a visible filler.</p></template>
          <template v-else-if="selectedId === 'hill'"><div class="formula mono">{{ JSON.stringify(result.metadata?.matrix) }} × [0,2,19] mod 26 = POH</div><p>Letter vectors are multiplied by an invertible key matrix.</p></template>
        </section>
        <section v-else class="terminal-panel technical-stage"><div class="step-focus"><span class="kicker">Step {{ stepIndex + 1 }} / {{ result.steps.length }}</span><h2>{{ currentStep?.title }}</h2><p class="transform mono">{{ currentStep?.input }} → {{ currentStep?.output }}</p><p>{{ currentStep?.detail }}</p></div><input v-model.number="stepIndex" type="range" min="0" :max="Math.max(0, result.steps.length - 1)" aria-label="Explanation step" /><div class="grid-2"><button class="button" type="button" :disabled="stepIndex === 0" @click="stepIndex--">Previous</button><button class="button button--primary" type="button" :disabled="stepIndex >= result.steps.length - 1" @click="stepIndex++">Next step</button></div></section>
        <section class="terminal-panel stack"><div><span class="kicker">Short exercise</span><h2>Try the method</h2></div><div class="field"><label for="exercise">Text to encrypt with the lesson key</label><input id="exercise" v-model="exercise" /></div><button class="button" type="button" :disabled="!exercise" @click="check">Reveal and compare</button><pre v-if="answer" class="exercise-answer">{{ answer }}</pre></section>
      </div>
    </section>
  </PageFrame>
</template>

<style scoped>
