solid var(--cg-line); }.technical-stage { display: grid; gap: 18px; }.step-focus { min-height: 190px; padding: 18px; background: var(--cg-dark); color: #fff; }.step-focus .kicker { color: #ff7a45; }.transform { font-size: 1.4rem; }.technical-stage input[type=range] { width: 100%; }.exercise-answer { padding: 14px; background: var(--cg-surface-2); white-space: pre-wrap; }
@media (min-width: 800px) { .learning-hero { grid-template-columns: 1fr 1fr; }.lesson-layout { grid-template-columns: 220px 1fr; }.lesson-index { grid-template-columns: 1fr; } }
